CREATE FUNCTION public.application_emails() RETURNS TABLE(application_id uuid, email text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
begin
  if not is_staff() then raise exception 'Only programme staff can view applicant emails'; end if;
  return query select a.id, au.email::text from applications a join auth.users au on au.id = a.applicant_id where a.status <> 'draft';
end $$;


--
-- Name: application_transition_allowed(public.application_status, public.application_status); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.application_transition_allowed(p_from public.application_status, p_to public.application_status) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $$
  select case p_from
    when 'submitted'   then p_to in ('under_review', 'rejected')
    when 'under_review' then p_to in ('shortlisted', 'waitlisted', 'accepted', 'rejected')
    when 'shortlisted' then p_to in ('under_review', 'waitlisted', 'accepted', 'rejected')
    when 'waitlisted'  then p_to in ('shortlisted', 'accepted', 'rejected')
    when 'rejected'    then p_to in ('under_review')       -- reconsideration, note required
    else false                                              -- draft is the applicant's; accepted is final
  end $$;


--
-- Name: apply_curriculum_v13_1(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_curriculum_v13_1() RETURNS TABLE(item text, outcome text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  prog constant uuid := '00000000-0000-0000-0000-0000000000a1';
  n record; s record; cs record; lp record; tn record; rec jsonb; old jsonb; obj text[]; act text[];
begin
  insert into curriculum_v13_1_previous(track_code, session_no, session, plan, notes)
  select v.track_code, v.session_no, v.session, v.plan, v.notes
    from curriculum_v13_sessions v join curriculum_v13_1_sessions x using (track_code, session_no)
  on conflict do nothing;

  for n in select * from curriculum_v13_1_sessions order by case when track_code = 'core' then 0 else 1 end, track_code, session_no loop
    item := case when n.track_code = 'core' then 'core' else n.track_code end || ' session ' || n.session_no;
    select * into s from curriculum_v13_1_previous where track_code = n.track_code and session_no = n.session_no;
    select c.* into cs from curriculum_sessions c left join tracks tk on tk.id = c.track_id
     where c.programme_id = prog and c.session_no = n.session_no
       and ((n.track_code = 'core' and c.track_id is null) or (n.track_code <> 'core' and tk.code = n.track_code));
    if not found then outcome := 'session not found here (the V13.1 source is used when it is loaded)'; return next; continue; end if;

    rec := n.session; old := s.session;
    obj := array(select jsonb_array_elements_text(rec -> 'objectives'));
    act := array(select jsonb_array_elements_text(rec -> 'activities'));
    if cs.is_approved then
      outcome := 'approved session record kept unchanged';
    elsif (cs.title, cs.description, cs.objectives, cs.activities, cs.expected_output, cs.assessment_notes)
          is not distinct from (rec ->> 'title', rec ->> 'description', obj, act, rec ->> 'expected_output', rec ->> 'assessment_notes') then
      outcome := 'session record already current';
    elsif (cs.title, cs.description, cs.objectives, cs.activities, cs.expected_output, cs.assessment_notes)
          is not distinct from (old ->> 'title', old ->> 'description', array(select jsonb_array_elements_text(old -> 'objectives')),
                                array(select jsonb_array_elements_text(old -> 'activities')), old ->> 'expected_output', old ->> 'assessment_notes') then
      update curriculum_sessions set title = rec ->> 'title', description = rec ->> 'description', objectives = obj, activities = act,
             expected_output = rec ->> 'expected_output', assessment_notes = rec ->> 'assessment_notes' where id = cs.id;
      outcome := 'session record updated';
    else
      outcome := 'session record kept (edited since V13)';
    end if;

    select * into lp from curriculum_lesson_plans where session_id = cs.id;
    select * into tn from curriculum_teaching_notes where session_id = cs.id;
    if lp.id is null then
      outcome := outcome || '; no lesson plan yet (the loader adds V13.1)';
    elsif lp.content = n.plan and tn.content is not distinct from n.notes then
      if lp.version <> 'V13.1' then update curriculum_lesson_plans set version = 'V13.1' where id = lp.id; end if;
      outcome := outcome || '; lesson plan already V13.1';
    elsif lp.status <> 'draft' then
      outcome := outcome || '; lesson plan kept (approved since V13 - apply the V13.1 changes through the normal review)';
    elsif lp.content = s.plan and tn.content is not distinct from s.notes then
      update curriculum_lesson_plans set content = n.plan, version = 'V13.1' where id = lp.id;
      update curriculum_teaching_notes set content = n.notes where id = tn.id;
      outcome := outcome || '; lesson plan and teaching notes updated to V13.1 (draft)';
    else
      outcome := outcome || '; lesson plan kept (edited since V13 - apply the V13.1 changes by hand)';
    end if;
    return next;
  end loop;

  -- later loads (a fresh database, or sessions created later) use V13.1
  update curriculum_v13_sessions v set session = x.session, plan = x.plan, notes = x.notes
    from curriculum_v13_1_sessions x where x.track_code = v.track_code and x.session_no = v.session_no;
end $$;


--
-- Name: apply_curriculum_v13_2(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_curriculum_v13_2() RETURNS TABLE(item text, outcome text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  prog constant uuid := '00000000-0000-0000-0000-0000000000a1';
  n record; s record; cs record; lp record; tn record; rec jsonb; old jsonb; obj text[]; act text[];
begin
  insert into curriculum_v13_2_previous(track_code, session_no, session, plan, notes)
  select v.track_code, v.session_no, v.session, v.plan, v.notes
    from curriculum_v13_sessions v join curriculum_v13_2_sessions x using (track_code, session_no)
  on conflict do nothing;

  for n in select * from curriculum_v13_2_sessions order by case when track_code = 'core' then 0 else 1 end, track_code, session_no loop
    item := case when n.track_code = 'core' then 'core' else n.track_code end || ' session ' || n.session_no;
    select * into s from curriculum_v13_2_previous where track_code = n.track_code and session_no = n.session_no;
    select c.* into cs from curriculum_sessions c left join tracks tk on tk.id = c.track_id
     where c.programme_id = prog and c.session_no = n.session_no
       and ((n.track_code = 'core' and c.track_id is null) or (n.track_code <> 'core' and tk.code = n.track_code));
    if not found then outcome := 'session not found here (the V13.2 source is used when it is loaded)'; return next; continue; end if;

    rec := n.session; old := s.session;
    obj := array(select jsonb_array_elements_text(rec -> 'objectives'));
    act := array(select jsonb_array_elements_text(rec -> 'activities'));
    if cs.is_approved then
      outcome := 'approved session record kept unchanged';
    elsif (cs.title, cs.description, cs.objectives, cs.activities, cs.expected_output, cs.assessment_notes)
          is not distinct from (rec ->> 'title', rec ->> 'description', obj, act, rec ->> 'expected_output', rec ->> 'assessment_notes') then
      outcome := 'session record already current';
    elsif (cs.title, cs.description, cs.objectives, cs.activities, cs.expected_output, cs.assessment_notes)
          is not distinct from (old ->> 'title', old ->> 'description', array(select jsonb_array_elements_text(old -> 'objectives')),
                                array(select jsonb_array_elements_text(old -> 'activities')), old ->> 'expected_output', old ->> 'assessment_notes') then
      update curriculum_sessions set title = rec ->> 'title', description = rec ->> 'description', objectives = obj, activities = act,
             expected_output = rec ->> 'expected_output', assessment_notes = rec ->> 'assessment_notes' where id = cs.id;
      outcome := 'session record updated';
    else
      outcome := 'session record kept (edited since V13.1)';
    end if;

    select * into lp from curriculum_lesson_plans where session_id = cs.id;
    select * into tn from curriculum_teaching_notes where session_id = cs.id;
    if lp.id is null then
      outcome := outcome || '; no lesson plan yet (the loader adds V13.2)';
    elsif lp.content = n.plan and tn.content is not distinct from n.notes then
      if lp.version <> 'V13.2' then update curriculum_lesson_plans set version = 'V13.2' where id = lp.id; end if;
      outcome := outcome || '; lesson plan already V13.2';
    elsif lp.status <> 'draft' then
      outcome := outcome || '; lesson plan kept (approved since V13.1 - apply the V13.2 changes through the normal review)';
    elsif lp.content = s.plan and tn.content is not distinct from s.notes then
      update curriculum_lesson_plans set content = n.plan, version = 'V13.2' where id = lp.id;
      update curriculum_teaching_notes set content = n.notes where id = tn.id;
      outcome := outcome || '; lesson plan and teaching notes updated to V13.2 (draft)';
    else
      outcome := outcome || '; lesson plan kept (edited since V13.1 - apply the V13.2 changes by hand)';
    end if;
    return next;
  end loop;

  -- later loads (a fresh database, or sessions created later) use V13.2
  update curriculum_v13_sessions v set session = x.session, plan = x.plan, notes = x.notes
    from curriculum_v13_2_sessions x where x.track_code = v.track_code and x.session_no = v.session_no;
end $$;


--
-- Name: apply_digital_marketing_approval_37(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_digital_marketing_approval_37() RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  prog constant uuid := '00000000-0000-0000-0000-0000000000a1';
  marker constant text := 'DIRA approval of 8 Nov 2026';
  dm uuid; n_moved int := 0; n_desc int := 0; n_topics int := 0; n_notes int := 0; bad text;
begin
  select id into dm from tracks where programme_id = prog and code = 'digital';
  if dm is null then return 'migration 37: no Digital Marketing track, nothing to do'; end if;

  -- refuse if any of the 11 has been reviewed (approved, rejected, reopened or with any history)
  select string_agg(p.title || ' (' || p.status || ')', '; ') into bad
    from curriculum_topic_proposals p join digital_marketing_topic_map_37() m on lower(btrim(p.title)) = lower(m.title)
   where p.track_id = dm
     and (p.status <> 'pending' or p.reviewed_by is not null or p.reviewed_at is not null
          or exists (select 1 from curriculum_topic_events e where e.proposal_id = p.id));
  if bad is not null then
    raise exception 'migration 37: these Digital Marketing topics have already been reviewed and are not moved: %. Nothing was changed.', bad;
  end if;

  -- refuse if a move would put the same topic twice on one session
  select string_agg(m.title, '; ') into bad
    from digital_marketing_topic_map_37() m
   where (select count(*) from curriculum_topic_proposals p where p.track_id = dm and lower(btrim(p.title)) = lower(m.title)) > 1;
  if bad is not null then
    raise exception 'migration 37: these Digital Marketing topics exist more than once: %. Nothing was changed.', bad;
  end if;

  -- 1. move to the V13.2 session (only pending, never-reviewed proposals reach this point)
  with target as (
    select m.title, cs.id as session_id from digital_marketing_topic_map_37() m
      join curriculum_sessions cs on cs.programme_id = prog and cs.track_id = dm and cs.session_no = m.current_session)
  update curriculum_topic_proposals p set session_id = t.session_id
    from target t where p.track_id = dm and lower(btrim(p.title)) = lower(t.title) and p.session_id <> t.session_id;
  get diagnostics n_moved = row_count;

  -- 2. the approval, visible to the reviewer in the Approval Centre
  update curriculum_topic_proposals p
     set description = format('Approved by DIRA on 8 Nov 2026 as a topic of Digital Marketing Session %s (owner''s written approval of '
                              'Sessions 5, 6 and 7, their topics and practical outputs; see docs/ASSUMPTIONS_AND_DECISIONS.md). '
                              'Taught in Session %s since the V13.2 revision. Awaiting formal approval in the Curriculum Approval Centre.',
                              m.approved_session, m.current_session)
    from digital_marketing_topic_map_37() m
   where p.track_id = dm and lower(btrim(p.title)) = lower(m.title) and p.status = 'pending'
     and p.description is distinct from format('Approved by DIRA on 8 Nov 2026 as a topic of Digital Marketing Session %s (owner''s written approval of '
                              'Sessions 5, 6 and 7, their topics and practical outputs; see docs/ASSUMPTIONS_AND_DECISIONS.md). '
                              'Taught in Session %s since the V13.2 revision. Awaiting formal approval in the Curriculum Approval Centre.',
                              m.approved_session, m.current_session);
  get diagnostics n_desc = row_count;

  -- 3. topics lists of the DRAFT records 3-7 = the proposals they carry (approved records are never edited)
  update curriculum_sessions cs
     set topics = coalesce((select array_agg(m.title order by m.approved_session, m.title) from digital_marketing_topic_map_37() m
                             where m.current_session = cs.session_no), '{}')
   where cs.programme_id = prog and cs.track_id = dm and cs.session_no between 3 and 7 and not cs.is_approved
     and cs.topics is distinct from coalesce((select array_agg(m.title order by m.approved_session, m.title) from digital_marketing_topic_map_37() m
                                              where m.current_session = cs.session_no), '{}');
  get diagnostics n_topics = row_count;

  -- 4. notes on the DRAFT records 3-8: which approved topics and outputs they carry forward
  update curriculum_sessions cs
     set assessment_notes = coalesce(cs.assessment_notes || ' ', '') || v.note
    from (values
      (3, marker || ' (Digital Marketing Sessions 5-7, topics and practical outputs): this session carries the approved topics "Digital footprint and online safety" and "Introduction to digital marketing" and the approved output "improved online profile" (all from approved Session 5). This V13.2 record itself is a draft awaiting session approval.'),
      (4, marker || ' (Digital Marketing Sessions 5-7, topics and practical outputs): this session carries the approved topics "Social media marketing (Facebook, Instagram, TikTok, LinkedIn)" (from approved Session 5) and "WhatsApp Business" and the approved output "WhatsApp Business profile plan" (both from approved Session 6). This V13.2 record itself is a draft awaiting session approval.'),
      (5, marker || ' (Digital Marketing Sessions 5-7, topics and practical outputs): this session carries the approved topics "Content planning and creation" (approved Session 5) and "Canva for marketing graphics" (from approved Session 6), the approved output "two-week content calendar" (approved Session 5) and the graphics for the approved output "three posts with captions" (from approved Session 6). This V13.2 record itself is a draft awaiting session approval.'),
      (6, marker || ' (Digital Marketing Sessions 5-7, topics and practical outputs): this session carries the approved topics "Marketing copywriting, captions and calls to action" (approved Session 6) and "SEO fundamentals" (from approved Session 7) and the captions for the approved output "three posts with captions" (approved Session 6). This V13.2 record itself is a draft awaiting session approval.'),
      (7, marker || ' (Digital Marketing Sessions 5-7, topics and practical outputs): this session carries the approved topics "Digital advertising fundamentals", "Marketing analytics and measuring campaign performance" and "Developing a practical digital marketing strategy" and the approved output "digital marketing portfolio project" (built here as the campaign plan) with practice of the "three-minute walk-through" (all approved Session 7). This V13.2 record itself is a draft awaiting session approval.'),
      (8, marker || ' (Digital Marketing Sessions 5-7, topics and practical outputs): this session delivers the approved output "three-minute walk-through" of the digital marketing portfolio project (from approved Session 7), now the three-minute campaign presentation. This V13.2 record itself is a draft awaiting session approval.')
    ) as v(session_no, note)
   where cs.programme_id = prog and cs.track_id = dm and cs.session_no = v.session_no and not cs.is_approved
     and position(marker in coalesce(cs.assessment_notes, '')) = 0;
  get diagnostics n_notes = row_count;

  return format('migration 37: %s proposal(s) moved, %s description(s) written, %s topics list(s) and %s note(s) updated; nothing approved',
                n_moved, n_desc, n_topics, n_notes);
end $$;


--
-- Name: assignment_visible_to_me(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assignment_visible_to_me(p_assignment uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select case when app_role() = 'participant' then
    (not exists (select 1 from assignment_recipients r where r.assignment_id = p_assignment)
     or exists (select 1 from assignment_recipients r where r.assignment_id = p_assignment and r.participant_id = my_participant_id()))
  else true end $$;


--
-- Name: audit_row(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.audit_row() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  insert into audit_logs(actor_id, table_name, row_id, action, old_data, new_data)
  values (auth.uid(), tg_table_name, coalesce((to_jsonb(new)->>'id'), (to_jsonb(old)->>'id')), tg_op,
          case when tg_op <> 'INSERT' then to_jsonb(old) end, case when tg_op <> 'DELETE' then to_jsonb(new) end);
  return coalesce(new, old);
end $$;


