-- Name: first_admin_needed(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.first_admin_needed() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
