--
-- Name: participant_completion(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.participant_completion(p_participant uuid, p_cohort uuid) RETURNS TABLE(sessions_attended integer, core_attended integer, core_total integer, final_submitted boolean, reflection_submitted boolean)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  with enrol as (select track_id from cohort_enrolments where participant_id = p_participant and cohort_id = p_cohort),
  sched as (
    select s.id, s.curriculum_session_id, cs.track_id from session_schedules s join curriculum_sessions cs on cs.id = s.curriculum_session_id
    where s.cohort_id = p_cohort and s.status <> 'cancelled'),
  att as (
    select distinct sc.curriculum_session_id, (sc.track_id is null) as is_core
    from sched sc join attendance a on a.schedule_id = sc.id
    where a.participant_id = p_participant and a.status in ('present', 'late')
      and (sc.track_id is null or sc.track_id = (select track_id from enrol)))
  select (select count(*)::int from att),
         (select count(*) filter (where is_core)::int from att),
         (select count(distinct curriculum_session_id)::int from sched where track_id is null),
         exists (select 1 from submissions sub join assignments asg on asg.id = sub.assignment_id
                 where sub.participant_id = p_participant and asg.cohort_id = p_cohort and asg.component = 'final_project'),
         exists (select 1 from submissions sub join assignments asg on asg.id = sub.assignment_id
                 where sub.participant_id = p_participant and asg.cohort_id = p_cohort and asg.component = 'reflection') $$;


--
-- Name: performance_cohorts(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.performance_cohorts() RETURNS TABLE(id uuid, name text, start_date date, end_date date)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select c.id, c.name, c.start_date, c.end_date from cohorts c
  where is_staff()
     or (app_role() = 'trainer' and c.id in (select my_trainer_cohorts()))
     or (app_role() = 'mentor' and exists (select 1 from cohort_enrolments e join mentorship_assignments m on m.participant_id = e.participant_id
                                            where e.cohort_id = c.id and m.mentor_id = auth.uid()))
  order by c.start_date desc $$;


--
-- Name: publish_due_briefs(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.publish_due_briefs() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare n int;
begin
  update daily_briefs set status = 'published', published_at = now() where status = 'scheduled' and publish_at <= now();
  get diagnostics n = row_count;
  return n;
end $$;


--
-- Name: queue_access_reminders(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.queue_access_reminders() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare r record; n int := 0; new_id uuid; kind_key text; fmt constant text := 'FMDay DD Mon YYYY HH24:MI';
begin
  if not email_automation_enabled() then return 0; end if;
  for r in
    select pa.profile_id as uid, e.cohort_id, c.name as cohort_name, g.timezone as tz,
           coalesce(a.opens_at_override, c.access_opens_at) as opens, coalesce(a.closes_at_override, c.access_closes_at) as closes
    from cohort_enrolments e
    join cohorts c on c.id = e.cohort_id
    join programmes g on g.id = c.programme_id
    join participants pa on pa.id = e.participant_id
    join profiles pr on pr.id = pa.profile_id
    left join learner_access a on a.participant_id = e.participant_id and a.cohort_id = e.cohort_id
    where pa.status <> 'withdrawn' and not coalesce(a.suspended, false) and not pr.email_opt_out and pr.status = 'active'
  loop
    if r.opens is not null and r.opens > now() and r.opens <= now() + interval '3 days' then
      kind_key := 'access_open:' || to_char(r.opens at time zone 'UTC', 'YYYYMMDDHH24MI');
      if not exists (select 1 from email_reminder_log l where l.kind = kind_key and l.ref_id = r.cohort_id and l.user_id = r.uid) then
        new_id := _enqueue_email(r.uid, 'access_opening_reminder', jsonb_build_object('cohort_name', r.cohort_name,
          'access_date', to_char(r.opens at time zone r.tz, fmt) || ' (' || r.tz || ')'), now(), 'reminder:access', null);
        insert into email_reminder_log(kind, ref_id, user_id) values (kind_key, r.cohort_id, r.uid) on conflict do nothing;
        if new_id is not null then n := n + 1; end if;
      end if;
    end if;
    if r.closes is not null and r.closes > now() and r.closes <= now() + interval '7 days' and (r.opens is not null and r.opens <= now()) then
      kind_key := 'access_close:' || to_char(r.closes at time zone 'UTC', 'YYYYMMDDHH24MI');
      if not exists (select 1 from email_reminder_log l where l.kind = kind_key and l.ref_id = r.cohort_id and l.user_id = r.uid) then
        new_id := _enqueue_email(r.uid, 'access_closing_reminder', jsonb_build_object('cohort_name', r.cohort_name,
          'access_date', to_char(r.closes at time zone r.tz, fmt) || ' (' || r.tz || ')'), now(), 'reminder:access', null);
        insert into email_reminder_log(kind, ref_id, user_id) values (kind_key, r.cohort_id, r.uid) on conflict do nothing;
        if new_id is not null then n := n + 1; end if;
      end if;
    end if;
  end loop;
  return n;
end $$;


--
-- Name: queue_reminders(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.queue_reminders() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare r record; n int := 0; new_id uuid;
begin
  if not email_automation_enabled() then return 0; end if;
  -- Sessions starting in the next 24 hours (not cancelled), for enrolled participants who have not opted out.
  for r in
    select s.id as ref, pa.profile_id as uid, cs.title, s.starts_at, s.mode, s.venue, s.meeting_url, c.name as cohort_name
    from session_schedules s join curriculum_sessions cs on cs.id = s.curriculum_session_id join cohorts c on c.id = s.cohort_id
    join cohort_enrolments e on e.cohort_id = s.cohort_id join participants pa on pa.id = e.participant_id
    join profiles pr on pr.id = pa.profile_id
    where s.status in ('scheduled', 'rescheduled') and s.starts_at > now() and s.starts_at <= now() + interval '24 hours'
      and pa.status <> 'withdrawn' and not pr.email_opt_out
      and (cs.track_id is null or cs.track_id = e.track_id)
      and not exists (select 1 from email_reminder_log l where l.kind = 'session' and l.ref_id = s.id and l.user_id = pa.profile_id)
  loop
    new_id := _enqueue_email(r.uid, 'session_reminder', jsonb_build_object('session_title', r.title,
      'session_date', to_char(r.starts_at at time zone 'Africa/Nairobi', 'FMDay DD Mon YYYY'), 'session_time', to_char(r.starts_at at time zone 'Africa/Nairobi', 'HH24:MI') || ' EAT',
      'session_mode', r.mode::text, 'session_place', coalesce(case when r.mode = 'physical' then 'Venue: ' || r.venue else 'Meeting link: ' || coalesce(r.meeting_url, 'will be shared by your trainer') end, ''), 'cohort_name', r.cohort_name), now(), 'reminder:session', null);
    insert into email_reminder_log(kind, ref_id, user_id) values ('session', r.ref, r.uid) on conflict do nothing;
    if new_id is not null then n := n + 1; end if;
  end loop;
  -- Assignments due in the next 48 hours that the participant has not submitted.
  for r in
    select a.id as ref, pa.profile_id as uid, a.title, a.due_at, c.name as cohort_name
    from assignments a join cohorts c on c.id = a.cohort_id join cohort_enrolments e on e.cohort_id = a.cohort_id
    join participants pa on pa.id = e.participant_id join profiles pr on pr.id = pa.profile_id
    where a.due_at > now() and a.due_at <= now() + interval '48 hours' and pa.status <> 'withdrawn' and not pr.email_opt_out
      and (a.track_id is null or a.track_id = e.track_id)
      and not exists (select 1 from submissions sb where sb.assignment_id = a.id and sb.participant_id = pa.id)
      and (not exists (select 1 from assignment_recipients ar where ar.assignment_id = a.id) or exists (select 1 from assignment_recipients ar where ar.assignment_id = a.id and ar.participant_id = pa.id))
      and not exists (select 1 from email_reminder_log l where l.kind = 'assignment' and l.ref_id = a.id and l.user_id = pa.profile_id)
  loop
    new_id := _enqueue_email(r.uid, 'assignment_reminder', jsonb_build_object('assignment_title', r.title,
      'due_date', to_char(r.due_at at time zone 'Africa/Nairobi', 'FMDay DD Mon YYYY HH24:MI') || ' EAT', 'cohort_name', r.cohort_name), now(), 'reminder:assignment', null);
    insert into email_reminder_log(kind, ref_id, user_id) values ('assignment', r.ref, r.uid) on conflict do nothing;
    if new_id is not null then n := n + 1; end if;
  end loop;
  return n;
end $$;


--
-- Name: record_file_scan(text, text, timestamp with time zone, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_file_scan(p_bucket text, p_name text, p_updated_at timestamp with time zone, p_result text, p_engine text DEFAULT NULL::text, p_detail text DEFAULT NULL::text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare s storage_file_scans; final text;
begin
  if p_result not in ('clean', 'infected', 'error') then raise exception 'Result must be clean, infected or error'; end if;
  select * into s from storage_file_scans where bucket_id = p_bucket and object_name = p_name for update;
  if not found then raise exception 'File not in the scan queue'; end if;
  insert into storage_file_scan_log(bucket_id, object_name, object_updated_at, result, engine, detail)
  values (p_bucket, p_name, p_updated_at, p_result, left(p_engine, 100), left(p_detail, 500));
  if s.object_updated_at <> p_updated_at then return 'superseded'; end if;   -- the file was replaced meanwhile; the new version is queued
  final := case p_result when 'error' then (case when s.attempts >= 3 then 'scan_failed' else 'pending' end) else p_result end;
  update storage_file_scans set status = final, scanned_at = case when p_result = 'error' then scanned_at else now() end,
         engine = coalesce(left(p_engine, 100), engine), detail = left(p_detail, 500), claimed_at = null
  where bucket_id = p_bucket and object_name = p_name;
  if final = 'infected' and s.uploaded_by is not null then
    insert into notifications(user_id, kind, title, body) values (s.uploaded_by, 'message', 'A file you uploaded was blocked',
      'Our virus check found a problem with ' || left(regexp_replace(p_name, '^.*/', ''), 100) || '. It cannot be opened. Please upload a clean copy.');
  end if;
  return final;
end $$;


--
-- Name: render_text(text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.render_text(t text, v jsonb) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    AS $$
declare k text; val text; out text := t;
begin
  for k, val in select * from jsonb_each_text(v) loop out := replace(out, '{{' || k || '}}', coalesce(val, '')); end loop;
  if out ~ '\{\{[a-z_]+\}\}' then raise exception 'Unresolved placeholder in template: %', (regexp_match(out, '\{\{[a-z_]+\}\}'))[1]; end if;
  return out;
end $$;


--
-- Name: requeue_stuck_emails(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.requeue_stuck_emails() RETURNS integer
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  with u as (update email_outbox set status = 'queued' where status = 'sending' and claimed_at < now() - interval '15 minutes' and attempts < 3 returning 1) select count(*)::int from u $$;


--
-- Name: review_curriculum_topic(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.review_curriculum_topic(p_id uuid, p_decision text, p_comment text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  actor uuid := auth.uid();
  p curriculum_topic_proposals;
  c text := nullif(btrim(p_comment), '');
  new_state topic_status;
begin
  if actor is null or not can_approve_curriculum() then
    raise exception 'Only the Founder, Co-Founder or a Super Administrator can approve or reject curriculum topics';
  end if;
  if p_decision is null or p_decision not in ('approve', 'reject', 'reopen') then raise exception 'The decision must be approve, reject or reopen'; end if;
  if c is not null and length(c) > 1000 then raise exception 'The comment is too long (1000 characters at most)'; end if;

  select * into p from curriculum_topic_proposals where id = p_id for update;
  if not found then raise exception 'Topic not found'; end if;

  if p_decision = 'reopen' then
    if p.status <> 'rejected' then raise exception 'Only a rejected topic can be reconsidered (this one is %)', p.status; end if;
    new_state := 'pending';
  else
    if p.status <> 'pending' then raise exception 'Only a pending topic can be approved or rejected (this one is %)', p.status; end if;
    if p_decision = 'reject' and c is null then raise exception 'Give a reason when rejecting a topic'; end if;
    new_state := case when p_decision = 'approve' then 'approved'::topic_status else 'rejected'::topic_status end;
  end if;

  perform set_config('dira.topic_review', 'on', true);
  update curriculum_topic_proposals set status = new_state,
    reviewed_by = case when new_state = 'pending' then null else actor end,
    reviewed_at = case when new_state = 'pending' then null else now() end,
    reviewer_comment = case when new_state = 'pending' then null else c end
  where id = p.id;
  insert into curriculum_topic_events(proposal_id, from_status, to_status, actor_id, comment) values (p.id, p.status, new_state, actor, c);
  insert into audit_logs(actor_id, table_name, row_id, action, old_data, new_data)
    values (actor, 'curriculum_topic_proposals', p.id::text, 'curriculum_topic_' || case p_decision when 'approve' then 'approved' when 'reject' then 'rejected' else 'reopened' end,
            jsonb_build_object('status', p.status), jsonb_build_object('status', new_state, 'title', p.title, 'session_id', p.session_id, 'comment', c, 'decided_at', now()));
  perform set_config('dira.topic_review', 'off', true);
  return jsonb_build_object('status', new_state);
end $$;


--
-- Name: revoke_certificate(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revoke_certificate(p_certificate uuid, p_reason text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare pprofile uuid; n int;
begin
  if coalesce(app_role() not in ('super_admin', 'founder', 'co_founder', 'programme_director'), true) then raise exception 'Only a super administrator or programme director can revoke certificates'; end if;
  if p_reason is null or length(trim(p_reason)) < 5 then raise exception 'A written reason is required'; end if;
  perform set_config('app.certificate_fn', '1', true);
  update certificates set revoked = true, revoked_at = now(), revoked_by = auth.uid(), revoked_reason = trim(p_reason)
    where id = p_certificate and not revoked;
  get diagnostics n = row_count;  -- PERFORM would overwrite FOUND, so count rows explicitly
  perform set_config('app.certificate_fn', '', true);
  if n = 0 then raise exception 'Certificate not found or already revoked'; end if;
  select p.profile_id into pprofile from certificates c join participants p on p.id = c.participant_id where c.id = p_certificate;
  insert into notifications(user_id, kind, title, body) values (pprofile, 'certificate', 'A certificate was withdrawn', 'Please contact the programme team if you have questions.');
end $$;


