--
-- Name: connect_conversations; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.connect_conversations (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    kind text NOT NULL,
    cohort_id uuid,
    learner_id uuid,
    facilitator_id uuid,
    locked boolean DEFAULT false NOT NULL,
    locked_by uuid,
    locked_at timestamp with time zone,
    last_message_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    started_by uuid,
    CONSTRAINT connect_conv_shape CHECK ((((kind = 'cohort'::text) AND (cohort_id IS NOT NULL) AND (learner_id IS NULL) AND (facilitator_id IS NULL)) OR ((kind = 'direct'::text) AND (learner_id IS NOT NULL) AND (facilitator_id IS NOT NULL) AND (cohort_id IS NULL)) OR ((kind = 'safeguarding'::text) AND (learner_id IS NOT NULL) AND (facilitator_id IS NULL) AND (cohort_id IS NULL)))),
