--
-- Name: v_cohort_capacity _RETURN; Type: RULE; Schema: public; Owner: -
--

CREATE OR REPLACE VIEW public.v_cohort_capacity WITH (security_invoker='true') AS
 SELECT c.id AS cohort_id,
    c.name,
    c.capacity,
    (count(e.id))::integer AS enrolled
   FROM (public.cohorts c
     LEFT JOIN public.cohort_enrolments e ON ((e.cohort_id = c.id)))
  GROUP BY c.id;


