--
-- Name: alumni alumni_ro; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY alumni_ro ON public.alumni FOR SELECT TO authenticated USING ((public.is_staff() OR (public.app_role() = 'me_officer'::public.role_code) OR ((public.app_role() = 'trainer'::public.role_code) AND public.trainer_can_see_participant(participant_id)) OR ((public.app_role() = 'mentor'::public.role_code) AND public.mentor_has_mentee(participant_id))));


--
-- Name: alumni alumni_self; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY alumni_self ON public.alumni FOR SELECT TO authenticated USING ((participant_id = public.my_participant_id()));


--
-- Name: alumni alumni_self_update; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY alumni_self_update ON public.alumni FOR UPDATE TO authenticated USING ((participant_id = public.my_participant_id())) WITH CHECK ((participant_id = public.my_participant_id()));


--
-- Name: alumni alumni_write; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY alumni_write ON public.alumni TO authenticated USING (public.is_staff()) WITH CHECK (public.is_staff());


--
-- Name: announcements ann_insert; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY ann_insert ON public.announcements FOR INSERT TO authenticated WITH CHECK (public.is_staff());


--
-- Name: announcements ann_read; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY ann_read ON public.announcements FOR SELECT TO authenticated USING (((cohort_id IS NULL) OR public.is_staff() OR (cohort_id IN ( SELECT public.my_trainer_cohorts() AS my_trainer_cohorts)) OR (cohort_id IN ( SELECT cohort_enrolments.cohort_id
   FROM public.cohort_enrolments
  WHERE (cohort_enrolments.participant_id = public.my_participant_id())))));


--
-- Name: announcements; Type: ROW SECURITY; Schema: public; Owner: -
--

ALTER TABLE public.announcements ENABLE ROW LEVEL SECURITY;

--
-- Name: application_documents appdocs_own; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY appdocs_own ON public.application_documents TO authenticated USING ((EXISTS ( SELECT 1
   FROM public.applications a
  WHERE ((a.id = application_documents.application_id) AND (a.applicant_id = auth.uid()))))) WITH CHECK ((EXISTS ( SELECT 1
   FROM public.applications a
  WHERE ((a.id = application_documents.application_id) AND (a.applicant_id = auth.uid())))));


--
-- Name: application_documents appdocs_staff; Type: POLICY; Schema: public; Owner: -
