--

CREATE POLICY apps_own_update ON public.applications FOR UPDATE TO authenticated USING (((applicant_id = auth.uid()) AND (status = ANY (ARRAY['draft'::public.application_status, 'submitted'::public.application_status])))) WITH CHECK (((applicant_id = auth.uid()) AND (status = ANY (ARRAY['draft'::public.application_status, 'submitted'::public.application_status]))));


