--
-- Name: assignment_recipients arc_delete; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY arc_delete ON public.assignment_recipients FOR DELETE TO authenticated USING ((public.is_staff() OR (EXISTS ( SELECT 1
   FROM public.assignments a
  WHERE ((a.id = assignment_recipients.assignment_id) AND (a.cohort_id IN ( SELECT public.my_trainer_cohorts() AS my_trainer_cohorts)))))));


--
-- Name: assignment_recipients arc_insert; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY arc_insert ON public.assignment_recipients FOR INSERT TO authenticated WITH CHECK ((public.is_staff() OR (EXISTS ( SELECT 1
   FROM public.assignments a
  WHERE ((a.id = assignment_recipients.assignment_id) AND (a.cohort_id IN ( SELECT public.my_trainer_cohorts() AS my_trainer_cohorts)))))));


--
-- Name: assignment_recipients arc_read; Type: POLICY; Schema: public; Owner: -
--

