--
-- Name: daily_briefs db_learner_read; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY db_learner_read ON public.daily_briefs FOR SELECT TO authenticated USING (((public.app_role() = 'participant'::public.role_code) AND public.brief_is_live(status, publish_at) AND ((cohort_id IS NULL) OR (cohort_id IN ( SELECT e.cohort_id
   FROM public.cohort_enrolments e
  WHERE (e.participant_id = public.my_participant_id()))))));


