--
-- Name: daily_briefs db_trainer_read; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY db_trainer_read ON public.daily_briefs FOR SELECT TO authenticated USING (((public.app_role() = 'trainer'::public.role_code) AND ((cohort_id IN ( SELECT public.my_trainer_cohorts() AS my_trainer_cohorts)) OR ((cohort_id IS NULL) AND public.brief_is_live(status, publish_at)))));


